const sampleProducts = [
  { id: 1, name: 'Laptop', category: 'Electronics', price: 1000 },
  { id: 2, name: 'Phone', category: 'Electronics', price: 500 },
  { id: 3, name: 'Shirt', category: 'Apparel', price: 50 },
  { id: 4, name: 'Shoes', category: 'Apparel', price: 80 },
  { id: 5, name: 'Watch', category: 'Accessories', price: 200 },
];

function getProductsByCategory(products, category) {
  /**
   * TODO:
   * Gunakan metode array immutable untuk mengembalikan array produk yang termasuk dalam kategori yang diberikan.
   */
  return products.filter(sampleProducts => sampleProducts.category === category)
}

function findProductById(products, id) {
  /**
   * TODO:
   * Gunakan metode array immutable untuk mengembalikan produk dengan ID yang cocok.
   */
    return products.find(sampleProducts => sampleProducts.id === id)
}

function calculateTotalPrice(products) {
  /**
   * TODO:
   * Gunakan metode array immutable untuk menghitung total harga semua produk.
   */
  return products.reduce((total, product) => total + product.price, 0);
}

function applyDiscount(products, discount) {
  /**
   * TODO:
   * Gunakan metode array immutable untuk mengembalikan array baru,
   * di mana setiap produk memiliki harga yang sudah dikurangi dengan diskon yang diberikan.
   */
  return products.map(product => ({
    ...product,
    price: product.price - (product.price * discount / 100)
  }));
}

console.log(getProductsByCategory(sampleProducts, 'Electronics')); // Should return products with id 1 and 2
console.log(calculateTotalPrice(sampleProducts)); // Should return 1830
console.log(applyDiscount(sampleProducts, 10)); // Should return products with prices reduced by 10%
console.log(findProductById(sampleProducts, 3)); // Should return the product with id 3

/**
 * TODO:
 * Buat sistem karakter game menggunakan Object Composition (bukan class).
 *
 * Gunakan nama object dan function berikut:
 *
 * Ability Functions:
 * - canWalk
 * - canAttack
 * - canHeal
 *
 * Factory Function:
 * - createCharacter(name, abilities)
 *
 * Ketentuan:
 *
 * 1. Buat ability function bernama canWalk(character)
 *    Method yang dihasilkan:
 *    walk() → "<name> sedang berjalan"
 *
 * 2. Buat ability function bernama canAttack(character)
 *    Method yang dihasilkan:
 *    attack() → "<name> menyerang musuh"
 *
 * 3. Buat ability function bernama canHeal(character)
 *    Method yang dihasilkan:
 *    heal() → "<name> menyembuhkan diri"
 *
 * 4. Buat factory function createCharacter(name, abilities)
 *    yang:
 *    - membuat object bernama character
 *    - memiliki property name
 *    - menggabungkan ability menggunakan Object.assign()
 *
 * 5. Buat object berikut menggunakan createCharacter:
 *
 *    warrior
 *    abilities:
 *    - canWalk
 *    - canAttack
 *
 *    priest
 *    abilities:
 *    - canWalk
 *    - canHeal
 *
 *    paladin
 *    abilities:
 *    - canWalk
 *    - canAttack
 *    - canHeal
 *
 * 6. Simpan semua karakter ke dalam array bernama characters.
 *
 * 7. Jalankan testing berikut:
 *
 * warrior.walk()
 * warrior.attack()
 *
 * priest.walk()
 * priest.heal()
 *
 * paladin.walk()
 * paladin.attack()
 * paladin.heal()
 */

class Character {
    constructor(name) {
        this.name = name;
    }
}

function canWalk(character) {
    return {
        walk(){
            console.log(`${character.name} sedang berjalan`);
        }
    }
}

function canAttack(character){
    return {
        attack(){
            console.log(`${character.name} menyerang musuh`);
        }
    }
}

function canHeal(character) {
    return {
        heal(){
            console.log(`${character.name} menyembuhkan diri`);

        }
    }

}

function createCharacter(name, abilities){
    const character = new Character(name)
    for (const ability of abilities){
        Object.assign(character, ability(character))
    }
    return character;
}

const warrior = createCharacter("Diluc", [
    canWalk,
    canAttack
]);

const priest = createCharacter("Barbara", [
    canWalk,
    canHeal
]);

const paladin = createCharacter("Jean", [
    canWalk,
    canAttack,
    canHeal
]);

warrior.walk()
warrior.attack()

priest.walk()
priest.heal()

paladin.walk()
paladin.attack()
paladin.heal()

/**
 * TODO:
 * Buat sebuah class bernama Rectangle.
 * 
 * Ketentuan:
 * 1. Constructor menerima parameter:
 *    - width
 *    - height
 * 
 * 2. Buat method:
 * 
 * getArea()
 * - Mengembalikan luas persegi panjang.
 * 
 * getPerimeter()
 * - Mengembalikan keliling persegi panjang.
 * 
 * isSquare()
 * - Mengembalikan true jika width dan height sama.
 * - Jika tidak sama kembalikan false.
 * 
 * 3. Buat instance dari class tersebut dan tampilkan:
 *    - luas
 *    - keliling
 *    - apakah dia persegi atau bukan
 */

class Rectangle {
    constructor(width, height) {
        this.width = width;
        this.height = height;
    }

    getArea(){
        //Luas = Height x Width
        return(this.height * this.width);
    }

    getPerimeter(){
        // K = 2x (P x L) Atau 2P + 2L
        return 2 * (this.width + this.height);
    }

    isSquare(){
    return this.width === this.height;
    }
}

const rectangle = new Rectangle(25, 10);

console.log("Area:", rectangle.getArea());
console.log("Perimeter:", rectangle.getPerimeter());
console.log("Is Square:", rectangle.isSquare());

/**
 * TODO:
 * 1. Buatlah class bernama Animal dengan ketentuan:
 *    - Memiliki properti:
 *      - name: string
 *      - age: int
 *      - isMammal: boolean
 *    - Memiliki constructor untuk menginisialisasi properti:
 *      - name
 *      - age
 *      - isMammal
 * 2. Buatlah class bernama Rabbit dengan ketentuan:
 *    - Merupakan turunan dari class Animal
 *    - Memiliki method:
 *      - eat yang mengembalikan nilai string `${this.name} sedang makan!`
 *    - Ketika diinstansiasi, properti isMammal harus bernilai true
 * 3. Buatlah class bernama Eagle dengan ketentuan:
 *    - Merupakan turunan dari class Animal
 *    - Memiliki method:
 *      - fly yang mengembalikan nilai string `${this.name} sedang terbang!`
 *    - Ketika diinstansiasi, properti isMammal harus bernilai false
 * 4. Buatlah instance dari class Rabbit bernama "myRabbit" dengan ketentuan:
 *    - properti name bernilai: "Labi"
 *    - properti age bernilai: 2
 * 5. Buatlah instance dari class Eagle bernama "myEagle" dengan ketentuan:
 *    - properti name bernilai: "Elo"
 *    - properti age bernilai: 4
 */


// Tulis kode di bawah ini


class Animal {
    constructor(name, age, isMammal) {
        this.name = name;
        this.age = age;
        this.isMammal = isMammal;
    }
}

class Rabbit extends Animal{
    constructor(name, age) {
        super(name, age, true)
    }
    eat(){
        return (`${this.name} sedang makan!`);
    }
}

class Eagle extends Animal {
    constructor(name, age) {
        super(name, age, false)
    }
    fly(){
        return (`${this.name} sedang terbang!`);   
    }
}

const myRabbit = new Rabbit("Labi", 2);
const myEagle = new Eagle("Elo", 4);

console.log(myRabbit.eat());
console.log(myEagle.fly());

/**
 * TODO:
 * Buatlah sistem class kendaraan menggunakan konsep polymorphism.
 *
 * Ketentuan:
 * 1. Buat class induk bernama Vehicle.
 * 2. Class Vehicle memiliki constructor dengan properti:
 *      - name
 *
 * 3. Class Vehicle memiliki method bernama move()
 *      yang menampilkan teks:
 *      "<name> sedang bergerak"
 *
 * 4. Buat 3 class turunan dari Vehicle:
 *      - Car
 *      - Boat
 *      - Airplane
 *
 * 5. Setiap class turunan HARUS override method move()
 *      dengan perilaku berbeda:
 *
 *      Car → "<name> melaju di jalan"
 *      Boat → "<name> berlayar di laut"
 *      Airplane → "<name> terbang di udara"
 *
 * 6. Buat array berisi object:
 *      - Car
 *      - Boat
 *      - Airplane
 *
 * 7. Loop array tersebut dan panggil method move()
 *
 * Tujuan latihan:
 * memahami polymorphism dimana method yang sama
 * menghasilkan perilaku berbeda tergantung objectnya.
 */


class vehicle {
    constructor(name) {
        this.name = name;
    }

    move(){
        console.log(this.name + " sedang bergerak");
    }
}

class Car extends vehicle {
    move(){
        console.log(this.name + " melaju di jalan");
    }

    makeSound(){
        console.log(this.name + " Brummm")
    }
}

class Boat extends vehicle {
    move(){
        console.log(this.name + " berlayar di laut");
    }

    makeSound(){
        console.log(this.name + " Whooooosh")
    }
}

class Airplane extends vehicle {
    move(){
        console.log(this.name + " terbang di udara");
    }

    makeSound(){
        console.log(this.name + " Ngggggg")
    }
}


const car = new Car("Avanza");
const boat = new Boat("Titanic");
const airplane = new Airplane("Boeing 737");
const vehicles = [car, boat, airplane];

for (const vehicle of vehicles) {
  vehicle.move();
  vehicle.makeSound();
}


